package com.supportsphere.util; import javafx.fxml.FXMLLoader; import javafx.scene.*; import javafx.stage.Stage; public final class SceneManager { private static Stage stage; private SceneManager(){} public static void init(Stage s){stage=s;} public static void show(String fxml,String title) throws Exception { FXMLLoader l=new FXMLLoader(SceneManager.class.getResource("/com/supportsphere/fxml/"+fxml)); Scene sc=new Scene(l.load()); sc.getStylesheets().add(SceneManager.class.getResource("/com/supportsphere/css/style.css").toExternalForm()); stage.setTitle(title); stage.setScene(sc); stage.setMinWidth(1050); stage.setMinHeight(700); stage.show(); } }
